const body = $input.first().json.body || $input.first().json;
const fields = (body.data && body.data.fields) ? body.data.fields : (body.fields ? body.fields : []);
const responseId = (body.data && body.data.responseId) ? body.data.responseId : 'unknown';

const getVal = (label) => {
  const f = fields.find(f => f.label && f.label.toLowerCase() === label.toLowerCase());
  if (!f || f.value === null || f.value === undefined) return '';
  if (Array.isArray(f.value)) return f.value.join(', ');
  return String(f.value).trim();
};

const rawPhone = getVal('Phone Number').replace(/\D/g, '');
const phone = rawPhone.startsWith('20') ? rawPhone : '20' + rawPhone;
const patientName = getVal('Full Name') || 'مريض';
const dob = getVal('Date of Birth');
const gender = getVal('Gender');
const chiefComplaint = getVal('Chief Complaint');
const allergies = getVal('Known Allergies') || 'لا يوجد';
const medications = getVal('Current Medications') || 'لا يوجد';
const conditions = getVal('Chronic Conditions') || 'لا يوجد';
const dentalConcerns = getVal('Dental Concerns');
const lastVisit = getVal('Last Dental Visit');
const surgeries = getVal('Previous Dental Surgeries') || 'لا يوجد';
const insurance = getVal('Insurance Provider') || 'Self-pay';
const emergName = getVal('Emergency Contact Name');
const emergPhone = getVal('Emergency Contact Phone');
const xrayConsent = getVal('X-Ray Consent') === 'Yes';
const doctorName = getVal('Doctor Name') || 'الدكتور';

if (!phone || phone.length < 10) {
  return [{ json: { error: true, reason: 'missing_phone', phone: '', patientName: 'مريض', responseId } }];
}
if (!chiefComplaint) {
  return [{ json: { error: true, reason: 'missing_complaint', phone, patientName, responseId } }];
}

const safe = (s) => String(s || '').replace(/'/g, "''");

return [{ json: {
  phone, patientName, dob, gender, chiefComplaint, allergies, medications,
  conditions, dentalConcerns, lastVisit, surgeries, insurance,
  emergName, emergPhone, xrayConsent, doctorName, responseId, error: false,
  safePhone: safe(phone), safeName: safe(patientName), safeDob: safe(dob),
  safeGender: safe(gender), safeComplaint: safe(chiefComplaint),
  safeAllergies: safe(allergies), safeMeds: safe(medications),
  safeConditions: safe(conditions), safeDentalConcerns: safe(dentalConcerns),
  safeLastVisit: safe(lastVisit), safeSurgeries: safe(surgeries),
  safeInsurance: safe(insurance), safeEmergName: safe(emergName),
  safeEmergPhone: safe(emergPhone), safeDr: safe(doctorName)
}}];

const extracted = $('Extract Tally Fields').first().json;
const pgRow = $input.first().json || {};
return [{ json: { ...extracted, duplicate_id: pgRow.duplicate_id || null, is_duplicate: !!(pgRow.duplicate_id) } }];

const groqRaw = $input.all()[0].json;
const intakeData = $('Extract Tally Fields').first().json;

let analysis = {};
try {
  const content = groqRaw.choices[0].message.content;
  analysis = JSON.parse(content);
} catch(e) {
  analysis = {
    risk_level: 'low', risk_score: 20, red_flags: [],
    staff_note_ar: 'مريض روتيني — لا ملاحظات خاصة',
    staff_note_en: 'Routine patient - no special notes',
    latex_free_needed: false,
    antibiotic_prophylaxis_needed: false,
    xray_approved: intakeData.xrayConsent,
    patient_message_ar: 'شكراً ' + intakeData.patientName + '! ✅ استلمنا بياناتك بنجاح. نتطلع نشوفك في موعدك! 😊',
    prep_instructions_ar: 'يرجى تفريش أسنانك جيداً قبل الزيارة وإحضار أي تقارير طبية سابقة.',
    recommended_priority: 'routine'
  };
}

const safe = (s) => String(s || '').replace(/'/g, "''");
const redFlagsStr = Array.isArray(analysis.red_flags) ? analysis.red_flags.join(', ') : (analysis.red_flags || '');

return [{ json: {
  ...intakeData,
  riskLevel: analysis.risk_level || 'low',
  riskScore: analysis.risk_score || 0,
  redFlags: redFlagsStr,
  staffNoteAr: analysis.staff_note_ar || '',
  staffNoteEn: analysis.staff_note_en || '',
  latexFree: analysis.latex_free_needed || false,
  antibioticNeeded: analysis.antibiotic_prophylaxis_needed || false,
  xrayApproved: analysis.xray_approved || false,
  patientMessageAr: analysis.patient_message_ar || '',
  prepInstructions: analysis.prep_instructions_ar || '',
  priority: analysis.recommended_priority || 'routine',
  safeStaffNote: safe(analysis.staff_note_ar || ''),
  safeRedFlags: safe(redFlagsStr),
  safePrep: safe(analysis.prep_instructions_ar || ''),
  safePatientMsg: safe(analysis.patient_message_ar || '')
}}];
